      "headers_bytes": 408,
      "headers_sha256": "a2d6e56c161b8a8209b0153755a4f45ec5d74ea73be124b871c3a23aefa068e7",
      "normalization": "UTF-8 HTML parse, entity decoding, whitespace collapse; offsets refer to normalized text.",
      "evidence": [
        {
          "offset": [2069, 2402],
          "quote_offset": [2187, 2209],
          "literal": "The Russo-Japanese War began in February 1904 (37th year of Meiji) and lasted for 18 months until it was brought to a close in August 1905 (38th year of Meiji) at the Portsmouth Peace Conference."
        },
        {
          "offset": [3099, 3177],
          "quote_offset": [3116, 3144],
          "literal": "It was then that President Theodore Roosevelt of the United States stepped in."
        },
        {
          "offset": [3241, 3387],
          "quote_offset": [3277, 3315],
          "literal": "After a month long negotiation, the Russo-Japanese Peace Treaty was signed on September 5, 1905 (38th year of Meiji) and ratified on October 16th."
        },
        {
          "offset": [3388, 3469],
          "quote_offset": [3388, 3469],
          "literal": "The instruments of ratification were exchanged in Washington D.C. on November 25."
        }
