        {
          "kind": "source",
          "sha256": "37f823fb0a944aa937e786b7ed31159edac729b3ba9f72ce260392782e84f909",
          "basis": "NDL states that the Charter Oath called for deliberative assemblies and state affairs decided by public opinion."
        },
        {
          "kind": "editorial",
          "sha256": "37f823fb0a944aa937e786b7ed31159edac729b3ba9f72ce260392782e84f909",
